const sectionFor=p=>(/^(general|networking)\./.test(p))?'general':p.startsWith('fleet.')?'fleet':p.startsWith('sources')?'sources':p.startsWith('history.')?'history':p.startsWith('alerts.')?'alerts':'maintenance';
