const card=(title,body,subtitle='')=>`<section class="settings-card"><div class="settings-card-heading"><h3>${esc(title)}</h3>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${body}</section>`;
function fieldHTML(f,value,{scope='personal',editable=true,errors=[],path=f.key}={}){
 const shown=scope==='personal'&&typeof value==='number'&&['leftWidth','rightWidth','waterfallRatio','fleetHeight','inspectorHeight','attentionHeight'].includes(f.key)?Math.round(value*10)/10:value;
 const full=scope+'.'+path,id='cfg-'+full.replace(/[^a-z0-9_-]/gi,'-'),error=errors.filter(e=>e.path===full||scope==='configuration'&&e.path===path).map(e=>e.message).join(' '),type=f.type;
 const attrs=`id="${id}" data-setting-scope="${scope}" data-setting-path="${esc(path)}" data-writable="${editable}" data-value-type="${esc(f.numeric?'number':type)}" ${editable?'':'disabled'} aria-invalid="${!!error}" aria-describedby="${id}-help ${id}-error"`;
 let control;if(type==='boolean')control=`<input type="checkbox" ${attrs} ${value?'checked':''}>`;
 else if(type==='select'||type==='enum')control=`<select ${attrs}>${f.options.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(f.optionLabels?.[v]||v)}</option>`).join('')}</select>`;
 else if(type==='string-array')control=`<textarea ${attrs} rows="2" placeholder="One address per line">${esc(Array.isArray(value)?value.join('\n'):'')}</textarea>`;
 else{const num=type==='integer'||type==='number';control=`<input type="${num?'number':type==='time'?'time':type==='origin'?'url':'text'}" ${attrs} value="${esc(shown??'')}" ${num?`min="${f.min}" max="${f.max}" step="${type==='integer'||f.key==='fontSize'?'1':'any'}"`:''} ${f.nullable?'data-nullable="true" placeholder="Automatic / unset"':''} ${!num&&f.max?`maxlength="${f.codePoints?f.max*2:f.max}"`:''} autocomplete="off" spellcheck="false">`;}
 return `<div class="settings-field ${type==='boolean'?'is-toggle':''} ${error?'has-error':''}" data-field="${esc(full)}"><label for="${id}"><span>${esc(f.label)}${f.unit?` <small>${esc(f.unit)}</small>`:''}</span>${scope==='configuration'&&f.restartRequired?'<span class="settings-restart">RESTART</span>':''}</label>${control}<p id="${id}-help" class="settings-field-help">${esc(f.help||'')}</p><p id="${id}-error" class="settings-field-error" ${error?'':'hidden'}>${esc(error)}</p></div>`;
}
const personalHTML=(s,section,c)=>`<div class="settings-fields">${PERSONAL_FIELDS.filter(f=>!f.retired&&f.section===section).map(f=>fieldHTML(f,s.draft.personal[f.key],{editable:canUseCapability(s,'personalWrite'),errors:c.errors})).join('')}</div>`;
function adminHTML(s,section,c){if(s.role!=='admin'||!s.draft.configuration)return note('Hub configuration is private to administrators. Personal display settings remain independent.');return `<div class="settings-fields">${adminFields().filter(f=>f.section===section&&f.type!=='array'&&(f.path!=='general.installationRole'||!canUseCapability(s,'installationManage'))).map(f=>fieldHTML(f,getPath(s.draft.configuration,f.path),{scope:'configuration',path:f.path,editable:canUseCapability(s,'configurationWrite')&&!(f.path==='alerts.presentation.sound'&&!canUseCapability(s,'sound'))&&!(f.path==='general.installationRole'&&!canUseCapability(s,'installationRole')),errors:c.errors})).join('')}</div>`;}
function table(rows,columns,empty='No records were returned.'){if(!Array.isArray(rows)||!rows.length)return note(empty);return `<div class="settings-table-scroll"><table><thead><tr>${columns.map(c=>`<th scope="col">${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,256).map(r=>`<tr>${columns.map(c=>`<td>${esc(c.get?c.get(r):r[c.key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
const rowsFrom=(d,k)=>Array.isArray(d)?d:Array.isArray(d?.[k])?d[k]:Array.isArray(d?.items)?d.items:[];
export function renderSettingsImpact(state,{requiresRestart=false,personal}={}){
 const changes=settingsChanges(state),fields=[...PERSONAL_FIELDS.map(f=>({...f,scope:'personal',path:f.key})),...adminFields().map(f=>({...f,scope:'configuration'}))];
 const display=(value,path)=>/password|secret|token|credential/i.test(path)?'Protected value':Array.isArray(value)?value.length+' items':value&&typeof value==='object'?'Structured settings':typeof value==='number'?String(Math.round(value*100)/100):String(value??'Unset');
 const rows=Object.entries(changes).flatMap(([scope,paths])=>paths.map(path=>{const f=fields.find(f=>f.scope===scope&&f.path===path);return {name:f?.label||path,before:display(getPath(state.baseline[scope],path),path),after:display(getPath(state.draft[scope],path),path),audience:scope==='personal'?'Your display':'Shared hub / collectors',effect:scope==='personal'?'Applied to this browser after Save':f?.restartRequired?'Saved configuration; managed restart required':'Saved configuration; verify source acknowledgment separately'};}));
 const applied=personal&&JSON.stringify(normalizePersonalSettings(personal))===JSON.stringify(state.baseline.personal);
 return note(rows.length?rows.length+' draft '+(rows.length===1?'change':'changes')+'. No configuration is changed by this preview.':'No unsaved display or hub changes.')+table(rows,[{key:'name',label:'Setting'},{key:'before',label:'Before'},{key:'after',label:'After'},{key:'audience',label:'Who is affected'},{key:'effect',label:'How to verify'}],'The saved configuration is shown below.')+facts([['Saved personal profile','r'+(state.personalRevision??'Unavailable')],['Observed display effect',applied?'Saved profile is applied in this browser':'Not observed in this browser'],['Saved hub configuration',Number.isSafeInteger(state.revision)?'r'+state.revision:'Unavailable to this account'],['Hub / source effect',requiresRestart?'Awaiting managed restart; source acknowledgment not observed':'Effective source revision not exposed; inspect actual capture and diagnostics']])+note('Enrollment and account actions have their own explicit action buttons and revision checks. A saved endpoint alone does not prove successful collection.');
}
export function sourceDossiers(state,context={}){
 if(!canUseCapability(state,'sourcesRead'))return '';
 const sources=rowsFrom(context.resources?.sources?.data,'sources');if(!sources.length)return '';
 return card('Source dossiers',sources.slice(0,64).map(source=>{
  const host=source.hostId||source.id,observed=source.observed||{},events=(context.snapshot?.sessions||[]).filter(s=>s.hostId===host).map(s=>s.lastEventAt).filter(at=>Number.isFinite(Date.parse(at))).sort();
  const stages=[['Enrolled',source.revokedAt||source.disabled?'Disabled / revoked':'Recorded in source inventory'],['Authenticated',source.lastAuthenticatedAt?'Last observed '+source.lastAuthenticatedAt:'Successful authentication time not exposed'],['Connected',observed.status||'Not observed'],['Capturing',events.length?'Last recorded event '+events.at(-1):'No event time in this view'],['Acknowledged',source.lastAcknowledgedAt||'Not observed'],['Archived','Exact-version source coverage not exposed here']];
  return '<details class="source-dossier"><summary>'+esc(source.label||observed.name||source.id)+' · '+esc(source.id)+'</summary>'+facts(stages)+note('Stages are independent observations. Credential issuance, connection and capture do not prove archive custody. Usage archive receipts remain available in Usage.')+'</details>';
 }).join(''),'Observed stages, with unknown states kept explicit.');
}
