export function mergeAdministrationInventory(previous={},result={},key,{removeId}={}){
 const singular=key==='users'?'user':'source',updated=result[singular];
 const rows=Array.isArray(result[key])?result[key]:rowsFrom(previous,key).filter(row=>row.id!==removeId).map(row=>row.id===updated?.id?updated:row);
 if(updated&&!rows.some(row=>row.id===updated.id))rows.push(updated);
 return {...previous,revision:result.revision??previous.revision,[key]:rows};
}

