function arrayHTML(s,path,c){if(s.role!=='admin'||!s.draft.configuration)return note('Administrator access is required to view or edit these profiles.');const schema=SETTINGS_SCHEMA.find(f=>f.path===path),rows=getPath(s.draft.configuration,path)||[],editable=canUseCapability(s,'configurationWrite');return `<div class="settings-array-editor">${rows.map((r,i)=>`<details class="settings-row-editor" data-settings-row="${esc(path)}" data-settings-row-id="${esc(r.id||'')}" data-settings-row-index="${i}" ${i===0||c.errors?.some(e=>e.path.startsWith(path+'.'+i+'.'))?'open':''}><summary><b>${esc(r.label||r.id||'New profile')}</b><small>${esc(r.kind||r.deviceClass)}</small></summary><div class="settings-fields">${schema.fields.map(f=>fieldHTML({...f,key:f.path,help:f.type==='string-array'?'One address per line.':f.type==='path'?'Absolute path on its owning host; this does not install or browse there.':f.help||''},r[f.path]??f.default,{scope:'configuration',path:path+'.'+i+'.'+f.path,editable,errors:c.errors})).join('')}</div><button type="button" class="settings-remove" data-remove-row="${path}" data-row="${i}" ${editable?'':'disabled'}>Remove from draft</button></details>`).join('')||note('No configuration profiles. Observed devices remain available separately.')}<button type="button" data-add-row="${path}" ${editable?'':'disabled'}>${path==='sources'?'Add source profile':'Add host metadata'}</button>${note('Identity metadata does not enroll a machine, install a collector, grant access or dispatch work. Managed source settings define collection policy only after they reach an enrolled collector.')}</div>`;}
function layoutsHTML(s){const p=s.draft.personal,edit=canUseCapability(s,'personalWrite');return `<div class="settings-layout-create"><label for="settings-layout-name">New layout name</label><input id="settings-layout-name" maxlength="48" placeholder="Desk / wall / review" ${edit?'':'disabled'}><button type="button" data-action="capture-layout" ${edit&&p.layouts.length<8?'':'disabled'}>Capture current draft</button></div><div class="settings-layout-list">${p.layouts.map(l=>`<article><span><b>${esc(l.name)}</b><small>${l.id===p.activeLayoutId?'Selected · ':''}${esc(new Date(l.updatedAt).toLocaleString())}</small></span><button type="button" data-layout-apply="${esc(l.id)}" ${edit?'':'disabled'}>Use</button><button type="button" data-layout-update="${esc(l.id)}" ${edit?'':'disabled'}>Replace</button><button type="button" data-layout-remove="${esc(l.id)}" aria-label="Remove layout ${esc(l.name)}" ${edit?'':'disabled'}>×</button></article>`).join('')||note('No named layouts. Capture your current draft, then save. Layouts contain presentation settings and never host, project or event filters.')}</div>`;}
