export function normalizeAuditRows(data={}){return ['configuration','administration'].flatMap(stream=>(Array.isArray(data[stream])?data[stream]:[]).map((entry,index)=>({...entry,changedPaths:Array.isArray(entry.changedPaths)?entry.changedPaths.filter(x=>typeof x==='string'):[],stream,_order:index}))).sort((a,b)=>{const at=x=>Date.parse(x.at||x.time||x.timestamp);const aa=at(a),bb=at(b);return (Number.isFinite(bb)?bb:-Infinity)-(Number.isFinite(aa)?aa:-Infinity)||a.stream.localeCompare(b.stream)||a._order-b._order;});}
function resourceState(key,s,c){const r=c.resources?.[key],cap=key==='backups'?'backup':resourceCaps[key];if(!canUseCapability(s,cap))return note('Administrator access is required for this protected view.','neutral');return `<div class="settings-resource-heading"><button type="button" data-resource="${key}" ${r?.loading?'disabled':''}>${r?.loading?'Loading…':'Refresh '+(key==='sources'?'collector inventory':key==='audit'?'change history':key)}</button><span>${r?.data?'Loaded on demand · refresh for a new reading':'Not loaded'}</span></div>`+(r?.loading?note('Loading '+key+' from the hub…'):r?.error?note(r.error+' Use Refresh to retry. Your draft is kept.','error'):!r?.data?note('No response loaded. This does not mean there are no records.'): '');}
