  page.removeEventListener('focusin',movement);page.removeEventListener('pointerdown',pointer);page.removeEventListener('keydown',navigation);dialog.removeEventListener('wheel',pointer);dialog.removeEventListener('touchmove',pointer);
  if(!current||moved||!workspace.isOpen||!dialog.open||!workspace.contextCurrent(context)||workspace.section!==section||workspace.query!==query||page.activeElement!==fallback&&page.activeElement!==page.body)return;
